def t1(df: pd.DataFrame):
    required_cols = ['masfem', 'gender_mf', 'alldeaths', 'ndam15', 'wind', 'category', 'min', 'year', 'elapsedyrs']
    df = df.dropna(subset=required_cols)
    return TransformDataReturn(
            df=df, 
            column_mapping={frozenset(required_cols): 'ALL'},
            transform_verb='filter'
        )

def t2(df: pd.DataFrame):
    df['masfem_std'] = (df['masfem'] - df['masfem'].mean()) / (df['masfem'].std(ddof=0) if df['masfem'].std(ddof=0) != 0 else 1.0)
    return TransformDataReturn(
            df=df, 
            column_mapping={frozenset(['masfem']): 'masfem_std'},
            transform_verb='derive'
        )

def t3(df: pd.DataFrame):
    df['gender_mf'] = pd.to_numeric(df['gender_mf'], errors='coerce')
    df['log_ndam15'] = np.log1p(df['ndam15'].astype(float))
    df['wind'] = pd.to_numeric(df['wind'], errors='coerce')
    df['category'] = pd.to_numeric(df['category'], errors='coerce')
    df['min'] = pd.to_numeric(df['min'], errors='coerce')
    df['year'] = pd.to_numeric(df['year'], errors='coerce')
    df['elapsedyrs'] = pd.to_numeric(df['elapsedyrs'], errors='coerce')
    return TransformDataReturn(
            df=df, 
            column_mapping={frozenset(['gender_mf', 'ndam15', 'wind', 'category', 'min', 'year', 'elapsedyrs']): 'ALL'},
            transform_verb='impute'
        )

def t4(df: pd.DataFrame):
    required_cols = ['masfem_std', 'gender_mf', 'alldeaths', 'wind', 'category', 'min', 'year', 'elapsedyrs']
    df = df.dropna(subset=required_cols)
    df = df.reset_index(drop=True)
    return TransformDataReturn(
            df=df, 
            column_mapping={frozenset(required_cols): 'ALL'},
            transform_verb='filter'
        )

transform_funcs = [t1, t2, t3, t4]
